// Driver Availability & Commitment Validation Engine for Replanning
validateDriverAvailabilityAndCommitments(driver, bus, targetRoute = null, options = {}) {
  // 1 & 5. Check whether driver exists and is available
  if (!driver) {
    return {
      isValid: false,
      reason: "Driver unavailable",
      preferenceScore: 0
    };
  }

  const status = driver.availabilityStatus || driver.status;
  if (status === 'sick' || status === 'unavailable') {
    return {
      isValid: false,
      reason: "Driver unavailable (Medical / Sickness absence)",
      preferenceScore: 0
    };
  }

  if (status === 'on_break' || status === 'offline') {
    return {
      isValid: false,
      reason: "Driver unavailable (Off-duty / Mandatory rest)",
      preferenceScore: 0
    };
  }

  if (status !== 'active' && status !== 'standby' && status !== 'available') {
    return {
      isValid: false,
      reason: "Driver unavailable",
      preferenceScore: 0
    };
  }

  // 2 & 4. Check the driver's current assignment and route conflicts
  if (targetRoute) {
    const conflictingRoute = this.state.routes.find(r =>
      r.id !== targetRoute.id &&
      (r.assignedDriver === driver.name || (driver.currentAssignment && driver.currentAssignment === r.id) || (bus && bus.routeId && bus.routeId === r.id && r.id !== targetRoute.id))
    );
    if (conflictingRoute) {
      return {
        isValid: false,
        reason: `Driver already assigned to another route (${conflictingRoute.id})`,
        preferenceScore: 0
      };
    }
  }

  // 3. Check existing commitments
  if (driver.commitments && driver.commitments.length > 0) {
    return {
      isValid: false,
      reason: "Driver has an existing commitment",
      preferenceScore: 0
    };
  }

  // Driver location distance validation
  const target = options.targetCoords || (bus?.status === 'in_depot' ? [37.7550, -122.4050] : (bus?.coords || null));
  if (target && (driver.currentLocation || driver.lastKnownLocation)) {
    const loc = driver.currentLocation || driver.lastKnownLocation;
    const distMi = getDistanceMiles(loc, target);
    if (distMi > (options.maxDistanceMi || 15.0)) {
      return {
        isValid: false,
        reason: `Driver too far away (${(distMi * 1.60934).toFixed(1)} km / ${distMi.toFixed(1)} mi from location)`,
        preferenceScore: 0
      };
    }
  }

  // 6. Prefer candidates with an available driver and no commitment conflict
  const preferenceScore = status === 'standby' ? 25 : 15;

  return {
    isValid: true,
    reason: null,
    preferenceScore
  };
}

