/**
 * Computes a lightweight fingerprint of a route's current state.
 * Used to detect if the route has changed between recommendation generation
 * and dispatcher acceptance (stale-recommendation guard).
 * @param {object} route
 * @returns {string}
 */
function computeRouteVersionKey(route) {
  if (!route || !route.stops) return 'no-route';
  // Fingerprint = stop count + first-stop name + completed-stop count
  const completedCount = route.stops.filter(s => s.status === 'completed' || s.status === 'passed').length;
  const firstName = route.stops[0]?.name || '';
  return `${route.id}:stops=${route.stops.length}:completed=${completedCount}:first=${firstName}`;
}

class AppStore {

// FEASIBLE CANDIDATE FOUND
// --- Run the Greedy Insertion engine to get the exact insertionPosition ---
const greedyResult = replanningEngine.replan({
  type: 'urgent_add',
  studentStop: {
    name: studentData.stopName,
    coords: studentData.coords || studentData.pickupCoords || [37.77, -122.42],
    specialNeeds: studentData.specialNeeds || 'None'
  },
  destinationSchoolId: studentData.schoolId,
  requiredSeats: 1
}, {
  buses: [bestCandidate.bus],
  routes: bestCandidate.route ? [bestCandidate.route] : [],
  drivers: bestCandidate.driver ? [bestCandidate.driver] : []
});

// Use greedy position if available, otherwise fall back to first non-completed stop
let greedyInsertionPosition = greedyResult.insertionPosition;
if (greedyInsertionPosition == null) {
  greedyInsertionPosition = 0;
  const routeStops = bestCandidate.route ? bestCandidate.route.stops : [];
  for (let i = 0; i < routeStops.length; i++) {
    if (routeStops[i].status !== 'completed' && routeStops[i].status !== 'passed') {
      greedyInsertionPosition = i;
      break;
    }
  }
}

// Take a snapshot of the current route version for stale-recommendation detection
const routeVersionKey = computeRouteVersionKey(bestCandidate.route);

const beforeRoute = JSON.parse(JSON.stringify(bestCandidate.route));
const afterRoute = JSON.parse(JSON.stringify(bestCandidate.route));

// Apply stop insertion at the EXACT greedy-selected position
const urgentStop = {
  id: `ST-${bestCandidate.route.id}-URGENT`,
  name: studentData.stopName,
  coords: studentData.coords || studentData.pickupCoords || [37.77, -122.42],
  time: "07:45 AM",
  studentsCount: 1,
  status: "pending"
};
afterRoute.stops.splice(greedyInsertionPosition, 0, urgentStop);
afterRoute.totalStops = afterRoute.stops.length;
const progress = computeRouteProgress(afterRoute, bestCandidate.bus);
afterRoute.completedStops = progress.completedStops;
afterRoute.currentStop = progress.currentStop;
afterRoute.nextStop = progress.nextStop;
afterRoute.remainingStops = progress.remainingStops;
afterRoute.currentBusPosition = progress.currentBusPosition;
afterRoute.routeProgressPercentage = progress.routeProgressPercentage;

