queueAction(actionInput = {}) {
  const actionId = actionInput.actionId || `ACT-${Date.now()}-${Math.floor(Math.random() * 10000)}`;

  // Prevent duplicate actions
  const existing = this.state.pendingOfflineChanges.find(a => a.actionId === actionId || a.id === actionId);
  if (existing) {
    console.warn(`Duplicate action suppressed: ${actionId}`);
    return existing;
  }

  const userId = actionInput.userId || (this.state.currentUser ? this.state.currentUser.id : 'USR-DISPATCHER-01');
  const role = actionInput.role || (this.state.currentRole || 'dispatcher');
  const user = actionInput.user || (this.state.currentUser ? this.state.currentUser.name : 'Dispatcher');
  const actionType = actionInput.actionType || 'UNKNOWN_ACTION';
  const timestamp = actionInput.timestamp || new Date().toISOString();
  const errorMsg = actionInput.error || actionInput.errorMessage || null;

  // Strict 9-attribute schema per reviewer specification:
  // actionId, timestamp, userId/role, actionType, payload, status, retryCount, lastAttempt, error
  const actionItem = {
    actionId,
    id: actionId,
    timestamp,
    userId,
    role,
    user,
    actionType,
    payload: actionInput.payload || {},
    status: actionInput.status || 'PENDING',
    retryCount: actionInput.retryCount || 0,
    lastAttempt: actionInput.lastAttempt || null,
    error: errorMsg,
    errorMessage: errorMsg, // Alias for backward compatibility
    routeId: actionInput.routeId || null,
    busId: actionInput.busId || null,
    studentId: actionInput.studentId || null,
    description: actionInput.description || `${actionType} recorded locally`
  };

  this.state.pendingOfflineChanges.push(actionItem);
  this.savePendingOfflineChanges();

  // Log fallback triggered when queueing offline
  if (this.state.networkStatus !== 'online') {
    this.logFallbackTriggered("OFFLINE_STORE_AND_FORWARD", { actionId: actionItem.actionId, actionType: actionItem.actionType });
  }

  this.showToast(`[OFFLINE MODE] Action queued locally (${actionId}). Will sync when online.`, 'warning');
  this.notify();
  return actionItem;
}

queueOfflineChange(actionType, description, payload = {}) {
  return this.queueAction({
    actionType,
    description,
    payload,
    routeId: payload.routeId || null,
    busId: payload.busId || null,
    studentId: payload.studentId || null
  });
}

getPendingQueueCount() {
  return (this.state.pendingOfflineChanges || []).length;
}

syncPendingOfflineChanges(options = {}) {
  const { simulateFailure = false } = options;
  if (this.state.pendingOfflineChanges.length === 0) {
    this.showToast('System is synchronized with district servers.', 'info');
    return { success: true, count: 0, syncedCount: 0, failedCount: 0 };
  }

  const nowStr = new Date().toISOString();
  const displayTimeStr = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
  let syncedCount = 0;
  let failedCount = 0;

  // Fail sync if network is offline or failure simulation requested:
  // Never falsely show synced when network is unavailable!
  const isOfflineOrFailure = simulateFailure || this.state.networkStatus === 'offline';

  this.state.pendingOfflineChanges.forEach(action => {
    action.status = 'SYNCING';
    action.lastAttempt = nowStr;

    if (isOfflineOrFailure) {
      action.status = 'FAILED';
      action.retryCount = (action.retryCount || 0) + 1;
      action.error = 'Network connection unavailable / Cloud sync timeout';
      action.errorMessage = action.error;
      failedCount++;
    } else {
      action.status = 'SYNCED';
      action.error = null;
      action.errorMessage = null;
      syncedCount++;

      this.state.metrics.recentAuditLogs.unshift({
        id: `LOG-SYNC-${Date.now()}-${Math.floor(Math.random() * 100)}`,
        time: displayTimeStr,
        user: action.user || 'Dispatcher',
        event: `[SYNCED] ${action.description || action.actionType} (${action.actionId || action.id})`,
        status: 'SYNCHRONIZED'
      });
    }
  });

  // Retain failed/pending items in the local store-and-forward queue
  const remainingItems = this.state.pendingOfflineChanges.filter(a => a.status !== 'SYNCED');
  this.state.pendingOfflineChanges = remainingItems;
  this.savePendingOfflineChanges();
  this.state.lastSyncTimestamp = displayTimeStr;

  if (failedCount > 0) {
    this.showToast(`Sync failed: ${failedCount} item(s) retained locally in queue. Will retry when connection recovers.`, 'danger');
  } else if (syncedCount > 0) {
    this.showToast(`Synchronized ${syncedCount} pending local action(s) with Central Servers.`, 'success');
  }

  this.notify();
  return { success: failedCount === 0, syncedCount, failedCount };
}

retryFailedActions() {
  const failedItems = this.state.pendingOfflineChanges.filter(a => a.status === 'FAILED');
  if (failedItems.length === 0) {
    this.showToast('No failed actions to retry.', 'info');
    return { success: true, count: 0, syncedCount: 0, failedCount: 0 };
  }

  failedItems.forEach(action => {
    action.status = 'PENDING';
    action.error = null;
    action.errorMessage = null;
  });

  this.showToast(`Retrying ${failedItems.length} failed action(s)...`, 'info');
  return this.syncPendingOfflineChanges();
}

// =========================================================================
// GPS Failure & Telematics Management
// Supports 5 distinct states: LIVE, LAST_KNOWN, STALE, NO_SIGNAL, MANUAL
// Stores & returns: latitude, longitude, source, lastUpdated, ageSeconds
// =========================================================================
getBusGpsState(busId) {
  const bus = typeof busId === 'string' ? this.state.buses.find(b => b.id === busId) : busId;
  if (!bus) return null;

  const lat = bus.coords ? bus.coords[0] : (bus.latitude || 37.77);
  const lon = bus.coords ? bus.coords[1] : (bus.longitude || -122.42);

  const rawStatus = (bus.gpsStatus || 'live').toLowerCase();
  const lastSyncMs = bus._lastGpsSyncTimeMs || (Date.now() - (rawStatus === 'live' ? 15000 : 180000));
  const ageSeconds = Math.max(0, Math.floor((Date.now() - lastSyncMs) / 1000));

  let status = rawStatus;
  if (status !== 'no_signal' && status !== 'manual') {
    if (ageSeconds > 120) {
      status = 'stale';
    } else if (ageSeconds > 60) {
      status = 'last_known';
    } else {
      status = 'live';
    }
  }

  const statusUpper = status.toUpperCase(); // 'LIVE' | 'LAST_KNOWN' | 'STALE' | 'NO_SIGNAL' | 'MANUAL'
  const isLive = status === 'live';
  const isLastKnown = status === 'last_known';
  const isStale = status === 'stale';
  const isNoSignal = status === 'no_signal';
  const isManual = status === 'manual';

  const source = isLive
    ? 'live_gps'
    : (isManual ? 'manual_dispatcher' : (isNoSignal ? 'no_signal' : (isStale ? 'stale_telematics' : 'last_known')));

  const lastUpdated = bus.lastGpsSync || `${ageSeconds}s ago`;

  // Persist properties onto bus object for consistency
  bus.latitude = lat;
  bus.longitude = lon;
  bus.source = source;
  bus.lastUpdated = lastUpdated;
  bus.ageSeconds = ageSeconds;
  bus.gpsStatus = status;
  bus.gpsStatusUpper = statusUpper;

  return {
    latitude: lat,
    longitude: lon,
    source,
    lastUpdated,
    ageSeconds,
    status,
    statusUpper,
    isLive,
    isLastKnown,
    isStale,
    isNoSignal,
    isManual,
    trustLevel: isNoSignal ? 'NONE' : (isStale ? 'LOW' : (isLastKnown ? 'MEDIUM' : 'HIGH')),
    requiresVerification: isStale || isNoSignal
  };
}

updateBusLocationManually(busId, coords, locationName = '', reason = 'Dispatcher Manual Checkpoint') {
  const bus = this.state.buses.find(b => b.id === busId);
  if (!bus) return;

  const nowTimeStr = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
  const lat = parseFloat(coords[0]);
  const lon = parseFloat(coords[1]);

  bus.coords = [lat, lon];
  bus.latitude = lat;
  bus.longitude = lon;
  bus.gpsStatus = 'manual';
  bus.gpsStatusUpper = 'MANUAL';
  bus.source = 'manual_dispatcher';
  bus.isManualLocation = true;
  bus._lastGpsSyncTimeMs = Date.now();
  bus.lastKnownLocation = locationName || `Checkpoint at [${lat.toFixed(4)}, ${lon.toFixed(4)}]`;
  bus.lastGpsSync = `${nowTimeStr} (Dispatcher Manual Fix: ${reason})`;
  bus.lastUpdated = bus.lastGpsSync;
  bus.ageSeconds = 0;

  const changeDescription = `Manual location update for ${bus.id} to ${bus.lastKnownLocation}`;

  if (this.state.networkStatus !== 'online') {
    this.queueOfflineChange('MANUAL_BUS_LOCATION', changeDescription, {
      busId,
      coords: bus.coords,
      latitude: lat,
      longitude: lon,
      locationName: bus.lastKnownLocation,
      reason
    });
  }

  this.state.metrics.recentAuditLogs.unshift({
    id: `LOG-GPS-${Date.now()}`,
    time: nowTimeStr,
    user: this.state.currentUser ? this.state.currentUser.name : 'Dispatcher',
    event: `Manual Location Fix: ${bus.id} updated to "${bus.lastKnownLocation}". Reason: ${reason}.`,
    status: 'MANUAL_GPS_OVERRIDE'
  });

  // Log audit event: MANUAL_OVERRIDE
  this.logManualOverride("MANUAL_LOCATION_OVERRIDE", {
    busId,
    coords: bus.coords,
    latitude: lat,
    longitude: lon,
    locationName: bus.lastKnownLocation,
    reason
  });

  this.showToast(`Location for ${bus.id} updated manually to "${bus.lastKnownLocation}". Marked as Manual Fix.`, 'success');
  this.closeModal();
  this.notify();
}

setBusGpsStatus(busId, statusInput, locationName = null) {
  const bus = this.state.buses.find(b => b.id === busId);
  if (!bus) return;

  const status = (statusInput || 'live').toLowerCase(); // 'live' | 'last_known' | 'stale' | 'no_signal' | 'manual'
  bus.gpsStatus = status;
  bus.gpsStatusUpper = status.toUpperCase();

  const nowStr = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });

  if (status === 'live') {
    bus.isManualLocation = false;
    bus._lastGpsSyncTimeMs = Date.now();
    bus.lastGpsSync = `${nowStr} (Live Telematics Lock)`;
    bus.source = 'live_gps';
  } else if (status === 'no_signal') {
    bus.isManualLocation = false;
    bus._lastGpsSyncTimeMs = Date.now() - 300000; // 5m ago
    bus.lastGpsSync = `${nowStr} (Signal Lost)`;
    bus.source = 'no_signal';
  } else if (status === 'stale') {
    bus.isManualLocation = false;
    bus._lastGpsSyncTimeMs = Date.now() - 180000; // 3m ago (>120s)
    bus.lastGpsSync = `${nowStr} (Stale Telematics > 2m)`;
    bus.source = 'stale_telematics';
  } else if (status === 'last_known') {
    bus.isManualLocation = false;
    bus._lastGpsSyncTimeMs = Date.now() - 75000; // 75s ago (>60s)
    bus.lastGpsSync = `${nowStr} (Last Known Position)`;
    bus.source = 'last_known';
  } else if (status === 'manual') {
    bus.isManualLocation = true;
    bus._lastGpsSyncTimeMs = Date.now();
    bus.lastGpsSync = `${nowStr} (Dispatcher Manual Fix)`;
    bus.source = 'manual_dispatcher';
  }

  if (locationName) {
    bus.lastKnownLocation = locationName;
  }

  const gpsState = this.getBusGpsState(bus.id);

  if (status === 'no_signal' || status === 'stale') {
    this.logFallbackTriggered("GPS_DEGRADED", { busId, status: bus.gpsStatusUpper, locationName });
  }

  this.notify();
  return gpsState;
}

